--淡入和位移动画
function UIDailyTaskCell:PlayAnimation2(index)
    if self.container then
        local canvasGroup = KTool.GetComponent(self.container.gameObject, typeof(CanvasGroup))
        canvasGroup.alpha = 1
        local dts = self.container.gameObject:GetComponents(typeof(DOTweenAnimation))
        for i, dt in array_pairs(dts) do
            dt.delay = 0.07 + index * 0.04
            dt:CreateTween()
            dt:DORestart()
        end
    end
end

--这个只有淡入动画
function UIDailyTaskCell:PlayAnimation1()
    if self.container then
        local canvasGroup = KTool.GetComponent(self.container.gameObject, typeof(CanvasGroup))
        self.co = cs_coroutine.start(function()
            canvasGroup.alpha = 0
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))
            canvasGroup:DOFade(1, 0.25)
        end)
    end
end

--矫正不播放动画的节点位置
function UIDailyTaskCell:FixNormalSetting()
    if self.container then
        local canvasGroup = KTool.GetComponent(self.container.gameObject, typeof(CanvasGroup))
        canvasGroup.alpha = 1
        local rectTransform = KTool.GetComponent(self.container.gameObject, typeof(CS.UnityEngine.RectTransform))
        rectTransform.anchoredPosition = Vector2(0, 0)
    end
end

function UIDailyTaskCell:Awake()

end

function UIDailyTaskCell:FreshBaseUI(data)
    CfUtils.PlayAnimator(self.controller.transform:Find("Container"), "Play")
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting254, "DailyTaskVo", data.id)
    CfUtils.FillText(self.NameTxt, vo.taskDescription)--原先的任务名换成任务描述
    --CfUtils.FillText(self.TitleTxt, vo.taskDescription)
    CfUtils.FillText(self.TitleTxt, string.format("(%s/%s)", data.progress, vo.taskContent))

    CfUtils.FillText(self.TxtActive, "+"..vo.point)
    local isGet = data.status == 1
    local canvasGroup = self.controller.gameObject:EnsureComponent(typeof(CS.UnityEngine.CanvasGroup))
    KTool.SetActive(self.HasDrawnNode, isGet)
    --KTool.SetActive(self.HasReceived, isGet)
    KTool.SetActive(self.ProgressNode, not isGet)
    --KTool.SetActive(self.Normal, not isGet)
    local canJump = checkNumber(vo.openType) > 0
    UIEventProxy.Create(self.FontStyleButton.gameObject).onPointerClick = function(event)
        if canJump and (not isGet) then
            local goodsConfMgr = GoodsConfMgr:GetInstance()
            local row = goodsConfMgr:GetJumpModuleRow(vo.openType)
            goodsConfMgr:ExecuteJump(row, {})
        end
    end
    self.Slider.value = data.progress / vo.taskContent
    CfUtils.SetUISwitchImage(self.Slider.transform, (not isGet) and 1 or 2)
    KTool.SetActive(self.Slider.transform:GetChild(0), not isGet)
    KTool.SetActive(self.FontStyleButton, canJump and (not isGet))

    if isGet then
        canvasGroup.alpha = 0.5
    else
        canvasGroup.alpha = 1
        --KTool.SetActive(self.FontStyleButton, canJump)
        --CfUtils.FillText(self.ProgressBarText, string.format("(%s/%s)", data.progress, vo.taskContent))
    end
end

function UIDailyTaskCell:OnDestroy()
    if self.co then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIDailyTaskCell